Problem 1: Scrabble
#include &lt;cs50.h&gt;#include &lt;ctype.h&gt;#include &lt;stdio.h&gt;#include &lt;string.h&gt;int compute_score(string word);int points[] = {1, 3, 3, 2, 1, 4, 2, 4, 1, 8, 5, 1, 3, 1, 1, 3, 10, 1, 1, 1, 1, 4, 4, 8, 4, 10};int main(void){    string word1 = get_string("Player 1: ");    string word2 = get_string("Player 2: ");    int score1 = compute_score(word1);    int score2 = compute_score(word2);    if (score1 &gt; score2)    {        printf("Player 1 wins!
");        return 0;    }    else if (score1 &lt; score2)    {        printf("Player 2 wins!
");        return 0;    }    else    {        printf("Tie!
");        return 0;    }}int compute_score(string word){    int score = 0;    for (int i = 0; i &lt; strlen(word); i++)    {        if (isupper(word[i]))        {            score += points[word[i] - 'A'];        }        else if (islower(word[i]))        {            score += points[word[i] - 'a'];        }    }    return score;}
Problem 2: Readability
#include &lt;cs50.h&gt;#include &lt;ctype.h&gt;#include &lt;math.h&gt;#include &lt;stdio.h&gt;#include &lt;string.h&gt;int letters(string text);int sentences(string text);int words(string text);int main(void){    string text = get_string("Text: ");    int index = (int) round(0.0588 * letters(text) / words(text) * 100 -                            0.296 * sentences(text) / words(text) * 100 - 15.8);    if (index &lt; 1)    {        printf("Before Grade 1
");        return 0;    }    else if (index &gt;= 16)    {        printf("Grade 16+
");        return 0;    }    else    {        printf("Grade %i
", index);        return 0;    }}int words(string text){    int words = 1;    for (int i = 0; i &lt; strlen(text); i++)    {        if (text[i] == ' ')        {            words += 1;        }    }    return words;}int letters(string text){    int letters = 0;    for (int i = 0; i &lt; strlen(text); i++)    {        if (isalpha(text[i]))        {            letters += 1;        }    }    return letters;}int sentences(string text){    int sentences = 0;    for (int i = 0; i &lt; strlen(text); i++)    {        if (text[i] == '.' || text[i] == '!' || text[i] == '?')        {            sentences += 1;        }    }    return sentences;}
Problem 3: Substitution
#include &lt;cs50.h&gt;#include &lt;ctype.h&gt;#include &lt;stdio.h&gt;#include &lt;string.h&gt;int main(int argc, string argv[]){    string key = argv[1];    if (argc != 2)    {        printf("Usage: ./substitution key
");        return 1;    }    else if (strlen(argv[1]) != 26)    {        printf("Key must contain 26 characters.
");        return 1;    }    else    {        for (int i = 0, n = strlen(key); i &lt; n; i++)        {            if (isalpha(argv[1][i]) == 0)            {                printf("Key should be all alphabets.
");                return 1;            }            for (int j = i + 1; j &lt; n; j++)            {                if (argv[1][i] == argv[1][j] || argv[1][i] + 32 == argv[1][j] ||                    argv[1][i] - 32 == argv[1][j])                {                    printf("There should be no duplicate in the key.
");                    return 1;                }            }        }        string ptext = get_string("plaintext:  ");        printf("ciphertext: ");        for (int i = 0, length = strlen(ptext); i &lt; length; i++)        {            if (isupper(ptext[i]))            {                char result = toupper(key[ptext[i] - 'A']);                printf("%c", result);            }            else if (islower(ptext[i]))            {                char result = tolower(key[ptext[i] - 'a']);                printf("%c", result);            }            else            {                printf("%c", ptext[i]);            }        }        printf("
");        return 0;    }}

