Problem 1: Songs
1.sql SELECT name FROM songs;
2.sql SELECT nameFROM songsORDER BY tempo;
3.sql SELECT nameFROM songsORDER BY duration_ms DESCLIMIT 5;
4.sql SELECT nameFROM songsWHERE danceability &gt; 0.75 AND energy &gt; 0.75 AND valence &gt; 0.75;
5.sql SELECT AVG(energy)FROM songs;
6.sql SELECT nameFROM songsWHERE artist_id = (    SELECT id    FROM artists    WHERE name = 'Post Malone');
